from az_lib import *
# ---- 11 Virtual networks
C(11,"How many IPs does Azure reserve in each subnet?","**Five:** the network address, the **first three** host addresses (gateway and Azure DNS) and the **broadcast** (last) address. A /24 gives **251** usable addresses. The smallest IPv4 subnet is **/29** (3 usable).")
C(11,"Address space rules for VNets?","Use private ranges (10/8, 172.16/12, 192.168/16). **Peered or connected VNets must not overlap.** You can **add** address ranges to a VNet later. A subnet in use cannot be resized past its resources.")
C(11,"Virtual network peering facts?","Connects two VNets over the **Microsoft backbone** with private IPs, low latency. **Regional or global** (cross-region). **Not transitive**: A↔B and B↔C does not give A↔C. Needs **Network Contributor** (or equivalent) on both sides. Address spaces must not overlap.")
C(11,"Gateway transit in hub-spoke?","The **hub** peering sets **Allow gateway transit**; the **spoke** peering sets **Use remote gateways**. The spoke then uses the hub's VPN/ExpressRoute gateway. A spoke that **has its own gateway** cannot use remote gateways.")
C(11,"Public IP SKUs?","**Standard:** always **static**, **secure by default** (closed until an NSG allows), zone-redundant or zonal, works with Standard Load Balancer. **Basic:** static or dynamic, open by default, **retired**. Dynamic IPs can change on deallocation.")
C(11,"User-defined routes (UDRs)?","A **route table** with routes (prefix → next hop), **associated to subnets**. Next hop types: **Virtual appliance** (an NVA IP), **Virtual network gateway** (VPN), **Virtual network**, **Internet**, **None** (drop).")
C(11,"How does Azure pick a route?","**Longest prefix match** first. If prefixes tie: **UDR** beats **BGP** beats **system** routes. A UDR can override system routes, including peering routes.")
C(11,"Spoke-to-spoke traffic in hub-spoke?","Peering isn't transitive, so add **UDRs** in each spoke sending the other spoke's range to an **NVA or Azure Firewall** in the hub (with IP forwarding on), or use **Azure Virtual Network Manager** / Virtual WAN.")
C(11,"Tools to troubleshoot connectivity?","**Effective routes** on a NIC, Network Watcher **Next hop** (which route wins), **IP flow verify** (which NSG rule allows or denies), **Connection troubleshoot** (end-to-end test), **Effective security rules**.")
Q(11,"You create a subnet with the address range 10.0.1.0/24. How many IP addresses can you assign to VMs?","251",["256","254","250"],"Azure reserves 5 addresses in every subnet.")
Q(11,"VNet1 is peered to VNet2, and VNet2 is peered to VNet3. VMs in VNet1 cannot reach VNet3. Why?","Peering is not transitive",["Global peering is not supported","VNet2 needs a public IP","The NSGs block port 443"],"You need a direct peering or routing through an NVA in VNet2.")
Q(11,"Spoke VNets must use the VPN gateway in the hub VNet. Which TWO settings are needed?",["Allow gateway transit on the hub peering","Use remote gateways on the spoke peering"],["Allow forwarded traffic on the gateway subnet","A public IP on each spoke"],"Gateway transit is set on the hub. Use remote gateways is set on the spoke.")
Q(11,"All internet-bound traffic from Subnet1 must pass through a firewall appliance at 10.0.0.4. What should you create?","A route table with 0.0.0.0/0 and next hop Virtual appliance 10.0.0.4, associated to Subnet1",["An NSG rule denying the internet","A peering to the firewall's VNet only","A service endpoint for Microsoft.Storage"],"A default route UDR sends traffic to the NVA.")
Q(11,"You cannot peer VNetA (10.1.0.0/16) with VNetB. VNetB uses 10.1.128.0/17. What is the cause?","The address spaces overlap",["The VNets are in different regions","VNetB has no gateway","Peering needs a Basic public IP"],"Peered VNets cannot have overlapping address spaces.")
YN(11,["A Standard public IP address can be dynamic.","A UDR can override a system route.","Global VNet peering connects VNets in different regions."],[0,1,1],"Standard IPs are always static. UDRs win on tie. Global peering is cross-region.")
M(11,"Match each next hop type to its use.",[("Send traffic to a firewall VM","Virtual appliance"),("Drop the traffic","None"),("Send traffic to an on-premises VPN","Virtual network gateway"),("Send traffic out to public addresses","Internet")],"Next hop decides where packets go.")
Q(11,"A VM cannot reach another subnet. You want to see which route wins for the destination IP. Which Network Watcher tool should you use?","Next hop",["IP flow verify","Packet capture","Connection Monitor"],"Next hop shows the route type, next hop IP and route table used.")
Q(11,"Two routes match 10.2.1.5: a system route for 10.2.0.0/16 and a UDR for 10.2.1.0/24. Which is used?","The UDR for 10.2.1.0/24",["The system route for 10.2.0.0/16","Both, load-balanced","Neither; traffic is dropped"],"Longest prefix match wins first.")
D(11,"Allow gateway transit","Use remote gateways","Set on the spoke's peering.",1,"Spokes use remote gateways. The hub allows transit.")
D(11,"Standard public IP","Basic public IP","Always static and closed until an NSG allows traffic.",0,"Standard is secure by default.")
D(11,"UDR","System route","Wins when both have the same prefix.",0,"User-defined routes beat system routes on a tie.")
D(11,"VNet peering","VPN gateway","Connects two Azure VNets over the backbone without a gateway.",0,"Peering needs no gateway.")
# ---- 12 Secure access to virtual networks
C(12,"How are NSG rules evaluated?","By **priority, 100 to 4096**, **lowest number first**. The **first match wins** and processing stops. Rules match on source, destination, port, protocol (5-tuple). NSGs are **stateful**: return traffic is allowed.")
C(12,"Default NSG rules?","**Inbound:** 65000 AllowVNetInBound, 65001 AllowAzureLoadBalancerInBound, **65500 DenyAllInbound**. **Outbound:** 65000 AllowVnetOutBound, 65001 AllowInternetOutBound, 65500 DenyAllOutBound. You **cannot delete** them, only override with lower numbers.")
C(12,"NSG on both the subnet and the NIC?","**Inbound:** subnet NSG first, then NIC NSG. **Outbound:** NIC NSG first, then subnet NSG. Traffic must be **allowed by both**. Check the result with **Effective security rules** or **IP flow verify**.")
C(12,"Application security groups (ASGs)?","Group **NICs by role** (WebServers, DbServers) and use the ASG as source or destination in NSG rules instead of IP addresses. All NICs in an ASG must be in the **same VNet**.")
C(12,"Service tags?","Named groups of Microsoft IP prefixes kept up to date by Azure, for NSG rules: **Internet, VirtualNetwork, AzureLoadBalancer, Storage, Sql, AzureCloud**, and regional versions like **Storage.WestEurope**.")
C(12,"Azure Bastion SKUs?","**Developer:** free, shared, one connection, no subnet. **Basic:** dedicated, 2 instances. **Standard:** native client, shareable links, IP-based connect, custom ports, file transfer, scaling 2-50. **Premium:** session recording, private-only. You can **upgrade, not downgrade**.")
C(12,"Bastion deployment requirements?","A subnet named exactly **AzureBastionSubnet**, **/26 or larger**, and a **Standard static public IP** (except Premium private-only). Users connect over **TLS 443** from the portal; target VMs need **no public IP**. Peered VNets are reachable (not with Developer).")
C(12,"Service endpoint?","Enabled **per subnet per service** (Microsoft.Storage, Microsoft.Sql…). Traffic to that service goes over the **Azure backbone** with the subnet's identity, so the PaaS firewall can allow the subnet. The service **keeps its public IP**. Free. Not reachable from on-premises.")
C(12,"Private endpoint?","A **NIC with a private IP** from your VNet mapped to **one specific resource** (a storage account's blob service, a SQL server). Reachable from **peered VNets and on-premises** (VPN/ExpressRoute). Needs **private DNS** (for example `privatelink.blob.core.windows.net`). Billed per hour and per GB.")
Q(12,"An NSG has rule 200 Allow TCP 3389 from Any and rule 100 Deny TCP 3389 from Any. What happens to RDP traffic?","It is denied by rule 100",["It is allowed by rule 200","It is allowed because allow rules win","It is denied by the default rule 65500"],"Lowest priority number is processed first, and processing stops at the first match.")
Q(12,"The subnet NSG allows inbound TCP 80. The NIC NSG has only the default rules. Can internet clients reach the VM on port 80?","No, the NIC NSG's DenyAllInbound blocks it",["Yes, the subnet NSG allows it","Yes, NSGs are stateful","No, because subnet NSGs are evaluated last"],"Inbound traffic must be allowed by both the subnet and the NIC NSG.")
Q(12,"You need admins to RDP to VMs from the Azure portal without any public IP on the VMs. What should you deploy?","Azure Bastion",["A NAT gateway","A Standard public IP on each VM","An application security group"],"Bastion provides RDP and SSH over TLS in the browser.")
Q(12,"On-premises users must reach a storage account over the VPN by a private IP, with public access disabled. What should you configure?","A private endpoint and a private DNS zone",["A service endpoint on the gateway subnet","A storage firewall IP rule for the on-premises range","Anonymous blob access"],"Private endpoints give a private IP reachable from on-premises. Service endpoints only work from the VNet.")
Q(12,"Which TWO are requirements for a Standard Azure Bastion deployment?",["A subnet named AzureBastionSubnet","A Standard SKU public IP address"],["A public IP on each target VM","A /29 subnet"],"AzureBastionSubnet must be /26 or larger, with a Standard public IP.")
YN(12,["You can delete the default DenyAllInbound rule in an NSG.","An ASG can be used as the destination of an NSG rule.","Service endpoints give a PaaS resource a private IP in your VNet."],[0,1,0],"Defaults can only be overridden. ASGs work as source or destination. Private endpoints, not service endpoints, give a private IP.")
M(12,"Match each requirement to the feature.",[("Allow web servers by role, not IP","Application security group"),("Allow all Azure Storage IPs in West Europe","Service tag"),("RDP from the browser with no public IP","Azure Bastion"),("Find which rule blocked a packet","IP flow verify")],"Group by role, by Microsoft range, by access path, by diagnosis.")
Q(12,"Which Bastion SKU do you need to connect with the native RDP client on your PC?","Standard",["Developer","Basic","Any SKU"],"Native client support starts at Standard.")
Q(12,"A storage account must accept traffic only from Subnet1. Cost must be minimal and on-premises access is not needed. What should you use?","A service endpoint and a virtual network rule",["A private endpoint","Azure Bastion","A VPN gateway"],"Service endpoints are free and meet the requirement.")
D(12,"Service endpoint","Private endpoint","Gives the PaaS resource a private IP that on-premises can reach.",1,"Private endpoints are NICs in your VNet.")
D(12,"Lower priority number","Higher priority number","Processed first.",0,"100 is checked before 4096.")
D(12,"ASG","Service tag","A Microsoft-maintained set of IP prefixes such as Storage.",1,"Service tags are Microsoft-defined. ASGs group your NICs.")
D(12,"Bastion Basic","Bastion Standard","Supports file transfer and shareable links.",1,"Those are Standard features.")
# ---- 13 Name resolution and load balancing
C(13,"Azure DNS public zones?","Host your domain's records in Azure. **Delegate** by setting the four Azure **NS records** at your registrar. Azure DNS does **not** sell domains. Records: A, AAAA, **CNAME (not at the zone apex)**, MX, NS, SOA, SRV, TXT, CAA, PTR.")
C(13,"Alias record sets?","Point an A, AAAA or CNAME record at an **Azure resource** (public IP, Traffic Manager, Front Door) so it **updates automatically** if the IP changes. Alias records **can be at the zone apex**, unlike CNAME.")
C(13,"Azure Private DNS zones?","Resolve names **only from VNets linked** to the zone. **Autoregistration** creates A records for **VMs** (primary NIC) in the linked VNet. A VNet can have **one registration zone**; a zone can have many registration VNets.")
C(13,"Custom DNS server and private zones?","If a VNet uses a **custom DNS server**, it **bypasses** Azure DNS and private zones. Forward to **168.63.129.16** (Azure-provided DNS) or use **Azure DNS Private Resolver**.")
C(13,"Azure Load Balancer basics?","**Layer 4** (TCP/UDP). **Public** (internet-facing frontend) or **internal** (private frontend). Parts: **frontend IP**, **backend pool**, **health probe**, **load-balancing rule**, **inbound NAT rule**, **outbound rule**. Basic SKU **retired 30 Sept 2025**.")
C(13,"Standard Load Balancer facts?","**Secure by default:** traffic needs an **NSG allow**. **Zone-redundant**, **99.99%** SLA, backend pool in **one VNet**, probes **TCP, HTTP, HTTPS**. Needs a **Standard public IP**. **HA ports** rule on internal LB balances all ports.")
C(13,"Session persistence modes?","**None** (5-tuple hash, default), **Client IP** (2-tuple: source and destination IP), **Client IP and protocol** (3-tuple). Use Client IP when a user must keep hitting the same VM.")
C(13,"Load Balancer vs Application Gateway vs Front Door?","**Load Balancer:** regional Layer 4. **Application Gateway:** regional Layer 7 (URL path routing, TLS termination, **WAF**, cookie affinity, needs its own subnet). **Front Door:** **global** Layer 7 with CDN and WAF.")
C(13,"Troubleshooting a load balancer?","Check the **health probe** (backend must answer on the probe port/path; probes come from **168.63.129.16** and the **AzureLoadBalancer** tag must be allowed), the **NSG** allows client traffic (Standard), the backends are in the **pool**, and the app listens on the backend port. Use **Insights** metrics: Health Probe Status, Data Path Availability.")
Q(13,"You want contoso.com (the zone apex) to point to a public IP of a load balancer and update automatically if the IP changes. What should you create?","An alias A record at the apex",["A CNAME record at the apex","An MX record","A PTR record"],"CNAME cannot be at the apex. An alias record tracks the Azure resource.")
Q(13,"VMs in VNet1 must resolve each other by name in contoso.internal, with records created automatically. What should you configure?","A private DNS zone linked to VNet1 with autoregistration enabled",["A public DNS zone with NS delegation","A custom DNS server with no forwarders","Host files on each VM"],"Autoregistration adds A records for VMs in a registration-linked VNet.")
Q(13,"A web app needs URL path-based routing (/images to one pool, /api to another) and a WAF. Which service should you use?","Azure Application Gateway",["Azure Load Balancer Standard","Azure Traffic Manager","An internal load balancer with HA ports"],"Path routing and WAF are Layer 7 features of Application Gateway.")
Q(13,"After deploying a Standard public load balancer, clients cannot reach the backend VMs on port 80. Probes are healthy. What is the most likely cause?","No NSG rule allows inbound TCP 80 to the backend",["Standard Load Balancer needs a Basic public IP","The backend pool must contain an availability set","Session persistence is set to None"],"Standard LB is secure by default; an NSG must allow the traffic.")
Q(13,"Which TWO components must exist for a load balancer to distribute HTTP traffic to backend VMs?",["A load-balancing rule","A health probe"],["An inbound NAT rule","A private DNS zone"],"Rules map frontend to backend, and probes decide which backends get traffic.")
YN(13,["Azure DNS can be used to buy a domain name.","A CNAME record can be created at the zone apex.","Health probes come from the IP address 168.63.129.16."],[0,0,1],"Buy domains elsewhere (or App Service domains). CNAME is not allowed at the apex. 168.63.129.16 is the probe source.")
M(13,"Match each requirement to the service.",[("Balance TCP traffic for internal VMs","Internal Load Balancer"),("Path-based routing with WAF in one region","Application Gateway"),("Global HTTP routing with CDN","Azure Front Door"),("Resolve VM names inside a VNet","Private DNS zone")],"Layer and scope decide.")
Q(13,"A VNet uses a custom DNS server, and VMs can no longer resolve names in a linked private DNS zone. What should you do?","Configure the custom DNS server to forward to 168.63.129.16",["Delete the virtual network link","Enable autoregistration on a second zone","Add a CNAME at the apex"],"Custom DNS bypasses Azure DNS unless it forwards to it.")
Q(13,"Users of a shopping app lose their session when sent to a different backend VM. What should you set on the load-balancing rule?","Session persistence to Client IP",["Idle timeout to 30 minutes","Floating IP","An outbound rule"],"Client IP affinity keeps a client on the same backend.")
D(13,"CNAME record","Alias record","Can be used at the zone apex.",1,"Alias records allow the apex.")
D(13,"Load Balancer","Application Gateway","Terminates TLS and routes by URL path.",1,"Layer 7 is Application Gateway.")
D(13,"Public DNS zone","Private DNS zone","Resolves names only from linked VNets.",1,"Private zones need VNet links.")
D(13,"Front Door","Application Gateway","Global Layer 7 entry point.",0,"Front Door is global. App Gateway is regional.")
# ---- 14 Monitoring
C(14,"Metrics vs logs in Azure Monitor?","**Metrics:** numeric time series, near real time, lightweight, kept **93 days**; view in **Metrics explorer**. **Logs:** records of many types in a **Log Analytics workspace**, queried with **KQL**.")
C(14,"Activity log?","Subscription-level record of **control-plane** events (who created, changed or deleted what, service health). Kept **90 days**. Send it to a workspace with a diagnostic setting to keep longer or query with KQL.")
C(14,"Diagnostic settings?","Route a resource's **resource logs** and **platform metrics** to a **Log Analytics workspace**, a **storage account** (archive), **Event Hubs** (stream) or a partner. **Resource logs are not collected until you create one.**")
C(14,"Collecting VM data?","Install the **Azure Monitor Agent (AMA)** and create a **data collection rule (DCR)** that says what to collect (performance counters, Windows events, Syslog) and where to send it. The old Log Analytics agent is **retired**. **VM insights** uses AMA.")
C(14,"KQL basics to recognize?","`Heartbeat | where TimeGenerated > ago(1h) | summarize count() by Computer`. Operators: **where** (filter), **summarize** (aggregate), **project** (choose columns), **take** (sample), **sort**, **render timechart**. Tables: Heartbeat, Perf, Event, Syslog, AzureActivity.")
C(14,"Alert rule types?","**Metric** (threshold on a metric), **Log search** (KQL query on a schedule), **Activity log** (an event such as VM deleted, plus **Service Health** and **Resource Health** alerts), Smart detection, Prometheus.")
C(14,"Action group vs alert processing rule?","**Action group:** *who and how* to notify or act (email, SMS, push, voice, webhook, Logic App, Function, Automation runbook, ITSM). **Alert processing rule:** changes **fired** alerts: **add action groups** or **suppress** notifications, at a scope, on a **schedule** (maintenance windows). Suppression wins over adding.")
C(14,"Azure Monitor Insights?","Curated views per service: **VM insights** (performance, map of dependencies), **Storage insights** (capacity, availability, latency), **Network insights** (topology, health). Built on metrics and logs.")
C(14,"Network Watcher tools?","**IP flow verify** (allowed or denied, and by which rule), **NSG diagnostics**, **Next hop**, **Effective security rules**, **Connection troubleshoot**, **Packet capture**, **VPN troubleshoot**. **Connection Monitor** tests connectivity **continuously** and alerts. **VNet flow logs** replace NSG flow logs (no new NSG flow logs since 30 June 2025).")
Q(14,"You need to be notified by SMS when a VM's CPU stays above 90% for 15 minutes. What should you create?","A metric alert rule with an action group that sends SMS",["An activity log alert","A diagnostic setting to Event Hubs","An alert processing rule only"],"Metric alerts watch thresholds. Action groups send notifications.")
Q(14,"No alert notifications should be sent for VMs in RG1 every Saturday from 01:00 to 05:00, but alerts must still be recorded. What should you create?","An alert processing rule that suppresses notifications on a recurring schedule",["Disable the alert rules every Saturday","Delete the action group","A resource lock on RG1"],"Alert processing rules suppress action groups on a schedule while alerts still fire.")
Q(14,"You need to keep a storage account's resource logs for 2 years at the lowest cost. Where should the diagnostic setting send them?","A storage account",["Event Hubs","Metrics explorer","An action group"],"Archive to storage is cheapest for long retention.")
Q(14,"You need to be alerted when anyone deletes a VM in the subscription. Which alert type should you use?","Activity log alert",["Metric alert","Log search alert on Perf","Smart detection alert"],"Deletes are control-plane events in the activity log.")
Q(14,"Which TWO are needed to collect Windows event logs from VMs into a Log Analytics workspace?",["The Azure Monitor Agent","A data collection rule"],["An NSG flow log","An alert processing rule"],"AMA plus a DCR define and send the data.")
YN(14,["Resource logs are collected automatically without a diagnostic setting.","Activity log data is kept for 90 days by default.","An alert processing rule can add action groups to fired alerts."],[0,1,1],"Resource logs need a diagnostic setting. Activity log keeps 90 days. Processing rules add or suppress action groups.")
M(14,"Match each question to the Network Watcher tool.",[("Which NSG rule blocks this packet?","IP flow verify"),("Which route does traffic to 10.1.0.4 use?","Next hop"),("Alert me when latency to the app server rises","Connection Monitor"),("Record all traffic metadata in a VNet","VNet flow logs")],"One tool per question.")
Q(14,"Which KQL operator groups rows and counts them, as in counting heartbeats per computer?","summarize",["project","where","take"],"summarize aggregates. project picks columns. where filters.")
Q(14,"You want to see dependencies between VMs and the processes that connect them. What should you enable?","VM insights",["Storage insights","An activity log alert","Packet capture"],"VM insights includes a dependency map.")
D(14,"Action group","Alert processing rule","Suppresses notifications during a maintenance window.",1,"Processing rules modify fired alerts.")
D(14,"Metrics","Logs","Queried with KQL in a Log Analytics workspace.",1,"Logs use KQL.")
D(14,"IP flow verify","Connection Monitor","Continuously tests reachability and alerts on failure.",1,"Connection Monitor is ongoing. IP flow verify is a one-off check.")
D(14,"Activity log","Resource logs","Shows who deleted a resource.",0,"Control-plane events are in the activity log.")
# ---- 15 Backup and recovery
C(15,"Recovery Services vault vs Backup vault?","**Recovery Services vault:** **Azure VMs**, SQL and SAP HANA in VMs, **Azure Files**, MARS agent, MABS/DPM, and **Site Recovery**. **Backup vault:** **Azure Disks**, **Azure Blobs**, **Azure Database for PostgreSQL**, AKS.")
C(15,"Vault region rules?","Backup is **within a region**: the vault must be in the **same region** as the VMs it protects. You need a vault per region. Vaults can move between resource groups and subscriptions, **not regions**.")
C(15,"Backup policy for VMs?","**Schedule** (Standard: once a day; **Enhanced**: multiple times a day, hourly) and **retention** (daily, weekly, monthly, yearly). **Instant restore** snapshots are kept locally for fast restores. One policy can protect many VMs.")
C(15,"Vault storage redundancy?","**LRS, ZRS or GRS**. You can change it **only before** any items are backed up. **Cross Region Restore** (restore in the paired region any time) needs **GRS**.")
C(15,"VM restore options?","**Create a new VM**, **restore disks** (then build a VM yourself), **replace existing** disks, or **file recovery** (a script mounts the recovery point so you copy files).")
C(15,"Soft delete for Azure Backup?","Deleted backup data is kept **14 days by default** (configurable **14-180**) at no cost for the first 14. **Enhanced soft delete** can be made **always-on**. You **cannot delete a vault** while it holds items, including soft-deleted ones.")
C(15,"Azure Site Recovery for Azure VMs?","**Replicates** VMs continuously to a **secondary region** (the Recovery Services vault is in the **target** region). Recovery points: **crash-consistent** (about every 5 minutes) and **app-consistent**. **Recovery plans** group VMs, set start order and add scripts.")
C(15,"Site Recovery failover steps?","**Test failover** into an isolated VNet (no impact; then **clean up**). **Failover** to a recovery point → **Commit** → **Re-protect** (replicate back to primary) → **Failback** → re-protect again.")
C(15,"Backup reports and alerts?","**Backup reports** need **diagnostic settings** sending vault data to a **Log Analytics workspace**. **Built-in Azure Monitor alerts** fire for failures; route them with an **alert processing rule** and an **action group**. Metric alerts can alert on successful jobs.")
Q(15,"You need to back up Azure VMs in East US and West US. What is the minimum number of Recovery Services vaults?","2",["1","3","4"],"A vault protects VMs in its own region only.")
Q(15,"Which vault type should you create to back up Azure Blobs and Azure managed disks?","Backup vault",["Recovery Services vault","Key Vault","Storage account"],"Backup vault supports disks, blobs, PostgreSQL and AKS.")
Q(15,"You must validate a disaster recovery plan without affecting production replication. What should you run in Site Recovery?","A test failover into an isolated virtual network",["A planned failover","Commit failover","Disable replication"],"Test failover creates VMs in a test network without stopping replication.")
Q(15,"After failing over VMs to the secondary region and committing, what must you do before failing back?","Re-protect the VMs",["Delete the recovery plan","Run a test failover cleanup","Change the vault to LRS"],"Re-protect starts replication from the secondary back to the primary.")
Q(15,"You need to restore one deleted file from yesterday's backup of an Azure VM without restoring the whole VM. What should you use?","File recovery",["Create a new VM","Replace existing disks","Cross Region Restore"],"File recovery mounts the recovery point so you can copy files.")
Q(15,"Which TWO workloads are protected with a Recovery Services vault?",["Azure virtual machines","Azure file shares"],["Azure Blobs (vaulted)","Azure Database for PostgreSQL"],"Blobs and PostgreSQL use a Backup vault.")
YN(15,["You can change a vault's storage redundancy from GRS to LRS after backups have started.","Cross Region Restore requires a GRS vault.","Soft-deleted backup items are kept for 14 days by default."],[0,1,1],"Redundancy locks once items are protected. CRR needs GRS. Soft delete default is 14 days.")
M(15,"Match each Site Recovery action to its purpose.",[("Prove DR works without impact","Test failover"),("Make the failover permanent","Commit"),("Start replicating back to the primary","Re-protect"),("Fail over a group of VMs in order","Recovery plan")],"Test, commit, re-protect, plan.")
Q(15,"You want weekly backup reports across vaults. What must you configure first?","Diagnostic settings that send vault data to a Log Analytics workspace",["An alert processing rule","A second vault in the paired region","A resource lock on the vault"],"Backup reports read from Log Analytics.")
D(15,"Recovery Services vault","Backup vault","Protects Azure managed disks with operational backup.",1,"Disks use a Backup vault.")
D(15,"Azure Backup","Azure Site Recovery","Keeps VMs replicated to another region for failover.",1,"Site Recovery is DR replication.")
D(15,"Test failover","Failover","Runs in an isolated network with no impact on production.",0,"Test failover is a drill.")
D(15,"LRS vault","GRS vault","Needed for Cross Region Restore.",1,"CRR needs GRS.")
